import{_ as e,c as a,o as s,a2 as i}from"./chunks/framework.DdOM6S6U.js";const g=JSON.parse('{"title":"FilepondsScheduler","description":"","frontmatter":{"sidebarPos":3,"sidebarTitle":"FilepondsScheduler"},"headers":[],"relativePath":"system-reference/backend/scheduled-jobs/fileponds-scheduler.md","filePath":"system-reference/backend/scheduled-jobs/fileponds-scheduler.md","lastUpdated":1778363927000}'),t={name:"system-reference/backend/scheduled-jobs/fileponds-scheduler.md"},d=i(`<h1 id="filepondsscheduler" tabindex="-1">FilepondsScheduler <a class="header-anchor" href="#filepondsscheduler" aria-label="Permalink to &quot;FilepondsScheduler&quot;">​</a></h1><p><code>Unusualify\\Modularous\\Schedulers\\FilepondsScheduler</code></p><p>Artisan command that cleans up abandoned filepond uploads. It runs <strong>daily</strong> via the Modularous scheduler registration and can also be triggered manually at any time.</p><h2 id="signature" tabindex="-1">Signature <a class="header-anchor" href="#signature" aria-label="Permalink to &quot;Signature&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>modularous:fileponds:scheduler {--days=7}</span></span></code></pre></div><table><thead><tr><th>Option</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>--days</code></td><td><code>7</code></td><td>Delete temporary filepond records created more than this many days ago</td></tr></tbody></table><h2 id="what-it-does" tabindex="-1">What It Does <a class="header-anchor" href="#what-it-does" aria-label="Permalink to &quot;What It Does&quot;">​</a></h2><p>The command calls two <code>FilepondManager</code> methods in sequence:</p><h3 id="_1-filepond-cleartemporaryfiles-days" tabindex="-1">1. <code>Filepond::clearTemporaryFiles($days)</code> <a class="header-anchor" href="#_1-filepond-cleartemporaryfiles-days" aria-label="Permalink to &quot;1. \`Filepond::clearTemporaryFiles($days)\`&quot;">​</a></h3><p>Removes expired temporary uploads — filepond records in the <code>temporary_fileonds</code> table whose <code>created_at</code> is older than <code>$days</code> days.</p><p>Steps performed:</p><ol><li>Query <code>TemporaryFilepond</code> records where <code>created_at &lt; now()-&gt;subDays($days)</code></li><li>For each record, delete its storage directory (<code>{tmp_path}/{folder_name}/</code>)</li><li>Delete the database records</li><li>Scan the remaining tmp directories and remove any empty folders not referenced by a <code>TemporaryFilepond</code> record</li></ol><p>Returns the deleted collection, whose count is written to the log.</p><h3 id="_2-filepond-clearfolders" tabindex="-1">2. <code>Filepond::clearFolders()</code> <a class="header-anchor" href="#_2-filepond-clearfolders" aria-label="Permalink to &quot;2. \`Filepond::clearFolders()\`&quot;">​</a></h3><p>Removes orphaned storage folders from the main filepond file path — directories that exist on disk but are not referenced by any <code>Filepond</code> UUID in the database and are not the tmp path itself.</p><p>Steps performed:</p><ol><li>List all directories under <code>$file_path</code></li><li>Build an exclusion list: the tmp path + all UUIDs from <code>Filepond::all()</code></li><li>Delete any directory in the diff that still contains files</li></ol><h2 id="schedule" tabindex="-1">Schedule <a class="header-anchor" href="#schedule" aria-label="Permalink to &quot;Schedule&quot;">​</a></h2><p>Registered as <code>-&gt;daily()</code> in <code>BaseServiceProvider</code>. The default <code>--days=7</code> retention period is baked into the schedule entry:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$schedule</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">command</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;modularous:fileponds:scheduler --days=7&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">daily</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span></code></pre></div><h2 id="manual-usage" tabindex="-1">Manual Usage <a class="header-anchor" href="#manual-usage" aria-label="Permalink to &quot;Manual Usage&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Use the default 7-day retention</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> modularous:fileponds:scheduler</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Extend retention to 30 days</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> modularous:fileponds:scheduler</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --days=30</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Aggressive cleanup: delete anything older than 1 day</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> modularous:fileponds:scheduler</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --days=1</span></span></code></pre></div><h2 id="logging" tabindex="-1">Logging <a class="header-anchor" href="#logging" aria-label="Permalink to &quot;Logging&quot;">​</a></h2><p>On completion, writes an info entry to the <code>scheduler</code> log channel:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Modularous: Deleted {N} expired temporary fileponds in last {days} days</span></span></code></pre></div><p>No error handling wraps this command — exceptions propagate to the scheduler and are captured by Laravel&#39;s default scheduler error handling.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><code>flush:filepond</code> — the manual flush command that also clears filepond data on demand.</li><li><a href="/system-reference/backend/services/uploader/overview">FilepondManager</a> — the service class implementing <code>clearTemporaryFiles</code> and <code>clearFolders</code>.</li></ul>`,28),l=[d];function n(o,r,h,p,c,u){return s(),a("div",null,l)}const y=e(t,[["render",n]]);export{g as __pageData,y as default};
